@dataclass
class InitiatePaymentFlowArgs:
    """InitiatePaymentFlowArgs holds the arguments for the initiate-payment-flow endpoint.
    """

    amount: str = field(metadata={"wire_name": "amount"})
    """The payment amount in the smallest currency unit (e.g. satang). For example,
    use 10000 for 100 THB. Must be a positive integer.
    """
    currency: str = field(metadata={"wire_name": "currency"})
    """The three-letter ISO currency code (e.g. THB). Must match the currency
    configured for your merchant account.
    """
    payment_session_id: str = field(metadata={"wire_name": "payment_session_id"})
    """The session ID received from our SDK after the customer selects
    their payment method. This connects the customer's payment method
    choice to this payment.
    """
    capture: bool = field(metadata={"wire_name": "capture"})
    """Controls when funds are captured. Set to true to capture funds
    immediately upon payment authorization, or false to only authorize
    funds for later capture. Useful for businesses that ship physical
    goods or need to verify orders before charging.
    """
    return_url: str = field(metadata={"wire_name": "return_url"})
    """The URL where we'll redirect your customer after they complete the
    payment flow. Should be a page that can handle both successful and
    failed payments.
    """
    external_id: Optional[str] = field(default=None, metadata={"wire_name": "external_id"})
    """Your unique reference for this payment, such as an order or invoice number. You
    can use this ID later to look up the payment instead of our payment ID. Must be
    unique within this merchant account's payments.
    1–128 characters after trimming leading and trailing whitespace. Must start
    with a letter or digit. Remaining characters may be letters, digits, periods
    (`.`), underscores (`_`), colons (`:`), slashes (`/`), or hyphens (`-`).
    Blank or whitespace-only values are stored as null.
    """
    card_id: Optional[str] = field(default=None, metadata={"wire_name": "card_id"})
    """The ID of a previously saved card (starting with `crd_`) or your own
    external card identifier. When provided for a card payment session that
    doesn't have a token attached, we'll use this saved card's token for the
    payment.

    Required when the payment session's payment method is CARD and no token
    was provided during select-payment-method.
    """
    customer_id: Optional[str] = field(default=None, metadata={"wire_name": "customer_id"})
    """Either a Customer ID (starting with `ctc_`) or your own external
    customer identifier. We'll link this payment to an existing customer
    if found, or create a new customer if not. This helps track payment
    history per customer.

    If you provide your own external ID and a customer with that ID
    doesn't exist, we'll create a new customer using that ID as their
    external identifier.
    """
    customer_email: Optional[str] = field(default=None, metadata={"wire_name": "customer_email"})
    """The customer's email address. If provided, we'll either:

    - Link this payment to an existing customer with this email
    - Create a new customer with this email if no match is found
    - Update the email for the customer specified in customer_id (if provided)
    """
    customer_mobile: Optional[str] = field(default=None, metadata={"wire_name": "customer_mobile"})
    """The customer's mobile number. If provided, we'll either:

    - Link this payment to an existing customer with this mobile
    - Create a new customer with this mobile if no match is found
    - Update the mobile for the customer specified in customer_id (if provided)
    """
    customer_name: Optional[str] = field(default=None, metadata={"wire_name": "customer_name"})
    """The customer's name. If provided, we'll either:

    - Update the name for an existing customer if found
    - Set the name when creating a new customer
    - Update the name for the customer specified in customer_id (if provided)
    """
    save_card: Optional[str] = field(default=None, metadata={"wire_name": "save_card"})
    """Option to save the card used in this payment session to the contact.
    Only applicable when the payment session uses a card token. The card will
    be saved if the token is multi-use.

    - `ADD`: Add the card to the contact without setting it as default
    - `DEFAULT`: Add the card to the contact and set it as the default card

    If any error occurs while saving the card, it will be silently ignored and
    will not block the payment flow.
    """
    interest_bearer: Optional[Literal["customer", "merchant"]] = field(default=None, metadata={"wire_name": "interest_bearer"})
    """Assertion that the payment session was locked to this interest
    bearer: `customer` or `merchant`. The interest bearer is fixed when
    the customer picks their plan in `select-payment-method`, and this
    only confirms it.

    Required when the payment session's payment method is INSTALLMENT,
    and it must be the same value that applied to
    `select-payment-method` for this session, otherwise the request is
    rejected. One of: "customer", "merchant".
    """

    @classmethod
    def _from_dict(cls, d: Dict[str, Any]) -> "InitiatePaymentFlowArgs":
        return cls(
            amount=d["amount"],
            currency=d["currency"],
            payment_session_id=d["payment_session_id"],
            capture=d["capture"],
            return_url=d["return_url"],
            external_id=d.get("external_id"),
            card_id=d.get("card_id"),
            customer_id=d.get("customer_id"),
            customer_email=d.get("customer_email"),
            customer_mobile=d.get("customer_mobile"),
            customer_name=d.get("customer_name"),
            save_card=d.get("save_card"),
            interest_bearer=d.get("interest_bearer"),
        )


