    async def initiate_payment_flow(self, args: InitiatePaymentFlowArgs) -> str:
        """## Initiate the payment flow

        Start a new payment flow using a payment session from our SDK. This endpoint
        creates a payment and returns a unique payment ID that you can use to track
        its status.

        The payment flow typically involves:

        1. Your customer selecting a payment method in the SDK
        2. You initiating the payment with the session ID from step 1
        3. The customer completing the payment via their selected payment method
        4. Our system notifying you of the final payment status via webhook, or you
           polling the status of the payment

        The payment ID returned by this endpoint can be used to track the payment status
        and details.

        Raises:
            webfunction.BadRequestError: code "NOT_FOUND" - The payment session ID provided doesn't match any active session in our system, or the card_id doesn't match any card belonging to the customer. This usually means the session has expired or was already used, or the card has been deleted. The customer should select their payment method again in the SDK to generate a new session.
            webfunction.BadRequestError: code "CONFLICT" - The payment session amount and currency do not match the amount and currency provided in the request. The payment session was created with specific values that must match when initiating the payment flow. Ensure the amount and currency in your request match the values used when creating the payment session. The payment external_id must also be unique within the merchant account.
            webfunction.BadRequestError: code "NOT_SUPPORTED" - The payment method selected does not support the requested operation. This occurs when capture is set to false but the payment method's integrations do not support authorization without capture. Choose a different payment method or set capture to true.
            webfunction.BadRequestError: code "CUSTOMER_REQUIRED" - A customer identifier is required when the payment session uses a saved card token. Provide customer_id, customer_email, or customer_mobile to identify the card's owner.
            webfunction.BadRequestError: code "CUSTOMER_MISMATCH" - The customer identifier provided does not match the saved card on the payment session. When the session was created with a saved card token, the customer_id or customer_email must belong to the card's owner.
            webfunction.UnexpectedStatusCodeError: if the server responds with a non-200/400 status
            webfunction.JsonParseError: if the response body isn't valid JSON
        """
        raw_args = _to_args_dict(args)
        result = await self._raw.call("initiate-payment-flow", raw_args)
        return cast(str, result)

    async def link_bank_account(self, args: LinkBankAccountArgs) -> str:
        """## Link bank account to a contact

        Link a bank account to a contact. This creates a new bank account record associated with the contact.

        - The bank account is added to the contact's list of bank accounts
        - If the contact has no bank account, this new account will automatically become the primary one
        - If the `primary` parameter is set to `true`, this account will be set as the primary bank account (replacing any existing primary account)
        - If the contact already has a primary bank account and `primary` is not set, this new account will be added as a secondary account

        The endpoint returns a unique identifier for the bank account that you can use to reference it in other API calls.

        Raises:
            webfunction.BadRequestError: code "NOT_FOUND" - No contact found with the provided contact_id.
            webfunction.BadRequestError: code "COUNTRY_MISMATCH" - The bank account's country code does not match your payment provider's country.
            webfunction.BadRequestError: code "INVALID_BANK_CODE" - The bank code is not valid for Thailand. Bank codes must be 3-digit codes assigned by the Bank of Thailand.
            webfunction.UnexpectedStatusCodeError: if the server responds with a non-200/400 status
            webfunction.JsonParseError: if the response body isn't valid JSON
        """
        raw_args = _to_args_dict(args)
        result = await self._raw.call("link-bank-account", raw_args)
        return cast(str, result)

